// Кейс: .qa/tests/monitoring/MON-022.md · план: .qa/e2e-app/specs/app.md (1.23)
// ПОЛУАВТОМАТ (@manual-assist): человек двигает телефон, скрипт ловит и проверяет. Сдвиги ×2 на вид (урок L-20261101-1):
// поворот ~90° вокруг вертикали ×2, стол → пол ×2, наклон ×2. На каждый сдвиг: «המכשיר זז» + тексты окна 10.2 →
// сбой держится ≥ 12 с (телефон положить и не трогать) → «כיוון מחדש» → 30 с на «כוונו את המצלמה מחדש» без окна сбоя
// поверх → галочка «כל שטח המים נראה בתמונה» → «חזרה לניטור» → «תקין» + событие «הניטור חזר לפעול».
// Ложные тревоги «זוהתה סכנה בבריכה» — #18bb68, НЕ провал, только лог.
// Только с BANCI_MONITORING=1 И BANCI_MANUAL_ASSIST=1 (в обычном регрессе — пропуск: без человека сдвигов не будет).
import { by, assert, skip, checkedFromValue } from '../../lib/appium.mjs';
import { waitEnabled } from '../../lib/banci.mjs';
import {
  requireMonitoringOptIn, startMonitoring, endMonitoring,
  MOVED, MOVED_TEXTS, MOVED_BUTTONS, logDangerAlarm, dangerClosed, dismissFalseDanger,
} from '../../lib/monitoring.mjs';

export const name = 'Реальные сдвиги ×2 (поворот, стол→пол, наклон): «המכשיר זז» каждый раз, держится до «כיוון מחדש», возврат «תקין» #8d2595 @iphone @app @data @manual-assist';

const MOVES = ['поворот ~90° вокруг вертикали', 'поворот ~90° вокруг вертикали', 'стол → пол (тот же угол)', 'стол → пол (тот же угол)', 'наклон (камера в потолок/вниз)', 'наклон (камера в потолок/вниз)'];
const ts = () => new Date().toTimeString().slice(0, 8);
// Окно сбоя 10.2 (а не строка события в «היסטוריית אירועים»): заголовок + кнопка «כיוון מחדש».
const movedWindow = async (app) => (await app.exists(by.exact(MOVED))) && (await app.exists(by.exact('כיוון מחדש', 'Button')));
const pause = (ms) => new Promise((r) => setTimeout(r, ms)); // интервал опроса, не ожидание результата

export default async function (app) {
  requireMonitoringOptIn();
  if (process.env.BANCI_MANUAL_ASSIST !== '1') skip('полуавтомат: сдвиги телефона делает человек — запуск только с BANCI_MANUAL_ASSIST=1 (и BANCI_MONITORING=1)');
  const waitSec = Number(process.env.BANCI_MOVE_WAIT_SEC || 180);
  const alarms = [];
  await startMonitoring(app);

  for (let i = 0; i < MOVES.length; i++) {
    const n = i + 1;
    console.log(`\n     ${ts()} СДВИГ ${n}/${MOVES.length}: ${MOVES[i]} — сделайте сейчас (до ${waitSec} с), потом положите телефон и не трогайте`);

    // 1. Ждём сбой «המכשיר זז» (ложные тревоги опасности только логируем).
    const end = Date.now() + waitSec * 1000;
    while (!(await movedWindow(app))) {
      assert(Date.now() < end, `сдвиг ${n} (${MOVES[i]}) → «${MOVED}» за ${waitSec} с (реальный сдвиг всегда даёт сбой — реджект rej_abb4c92d)`);
      if (!(await logDangerAlarm(app, alarms, `8d2595-move${n}`))) dangerClosed(alarms);
      await pause(600);
    }
    console.log(`     ${ts()} «${MOVED}» пойман → ${await app.screenshot(`8d2595-move-${n}`).catch(() => '—')}`);
    for (const t of MOVED_TEXTS) assert(await app.exists(by.contains(t)), `окно сбоя 10.2: текст «${t}»`);
    for (const b of MOVED_BUTTONS) assert(await app.exists(by.exact(b, 'Button')), `окно сбоя 10.2: кнопка «${b}»`);

    // 2. Сбой держится ≥ 12 с, даже когда телефон снова неподвижен (комм. программиста d27bfb4).
    const hold = Date.now() + 12000;
    while (Date.now() < hold) {
      assert(await movedWindow(app), `сдвиг ${n}: сбой «${MOVED}» не снимается сам за 12 с`);
      assert(!(await app.exists(by.exact('תקין'))), `сдвиг ${n}: статус не возвращается в «תקין» до «כיוון מחדש»`);
      await pause(1000);
    }

    // 3. «כיוון מחדש» → 30 с на «כוונו את המצלמה מחדש»: окно сбоя поверх не открывается.
    await app.tap(by.exact('כיוון מחדש', 'Button'), { what: '«כיוון מחדש» в окне сбоя' });
    await app.waitFor(by.contains('כוונו את המצלמה'), { timeout: 15000, what: 'экран «כוונו את המצלמה מחדש»' });
    const recal = Date.now() + 30000;
    while (Date.now() < recal) {
      if ((await movedWindow(app)) || (await app.exists(by.contains('כשל בניטור')))) {
        const shot = await app.screenshot(`8d2595-popup-${n}`).catch(() => undefined);
        assert(false, `сдвиг ${n}: окно сбоя не открывается поверх «כוונו את המצלמה מחדש» (скрин ${shot ?? '—'})`);
      }
      if (!(await logDangerAlarm(app, alarms, `8d2595-recal${n}`))) dangerClosed(alarms);
      await pause(700);
    }

    // 4. Галочка «כל שטח המים נראה בתמונה» → «חזרה לניטור» → «תקין» + «הניטור חזר לפעול».
    const cb = await app.scrollTo(by.begins('כל שטח המים נראה'), { max: 4, what: 'галочка «כל שטח המים נראה בתמונה»' });
    if (checkedFromValue(await cb.attr('value')) !== true) await cb.click();
    const back = await app.waitFor(by.exact('חזרה לניטור', 'Button'), { what: '«חזרה לניטור»' });
    await waitEnabled(back, true, { timeout: 20000, what: '«חזרה לניטור» (кадр освещён, линза открыта)' });
    await back.click();
    await app.waitFor(by.exact('תקין'), { timeout: 20000, what: `сдвиг ${n}: статус «תקין» после «חזרה לניטור»` });
    await app.waitFor(by.contains('הניטור חזר לפעול'), { timeout: 20000, what: `сдвиг ${n}: событие «הניטור חזר לפעול»` });
    assert(!(await movedWindow(app)), `сдвиг ${n}: после «חזרה לניטור» окна «${MOVED}» нет`);
    console.log(`     ${ts()} сдвиг ${n}: «חזרה לניטור» → «תקין» ✓`);
  }

  if (alarms.length) console.log(`     [#18bb68, не провал] ложных тревог опасности: ${alarms.length}`);
  await dismissFalseDanger(app);
  await endMonitoring(app);
}
